import { defineComponent, h, onBeforeUnmount, onMounted, shallowRef, watch, type PropType, type ShallowRef, type VNode } from 'vue';
import { SONNER_DEFAULT_DURATION, buildSonnerToastApi, createSonnerStore, getSonnerPositionStyleKeys, resolveSonnerTheme, sonnerStyleKeys } from '../lib/core';
import type { SonnerPosition, SonnerStore, SonnerTheme, SonnerToast, SonnerToastApi, SonnerType } from '../lib/core';
import styles from './sonner.module.scss';

const emptyToasts: SonnerToast[] = Object.freeze([]) as unknown as SonnerToast[];
const toasts = shallowRef<SonnerToast[]>(emptyToasts);
const activeOwner = shallowRef<symbol>();
const toasterOwners = new Map<symbol, number | undefined>();
let browserStore: SonnerStore | undefined;

function getBrowserStore(): SonnerStore | undefined {
	if (typeof window === 'undefined') return undefined;
	if (!browserStore) {
		browserStore = createSonnerStore();
		toasts.value = browserStore.getToasts();
		browserStore.subscribe(() => {
			toasts.value = browserStore!.getToasts();
		});
	}
	return browserStore;
}

const storeFacade: SonnerStore = {
	getToasts: () => getBrowserStore()?.getToasts() ?? emptyToasts,
	subscribe: (listener) => getBrowserStore()?.subscribe(listener) ?? (() => undefined),
	add: (input) => getBrowserStore()?.add(input) ?? '',
	update: (id, patch) => getBrowserStore()?.update(id, patch),
	dismiss: (id) => getBrowserStore()?.dismiss(id),
	remove: (id) => getBrowserStore()?.remove(id),
	dismissAll: () => getBrowserStore()?.dismissAll(),
	setDefaultDuration: (duration) => getBrowserStore()?.setDefaultDuration(duration),
};

function applyToasterPolicy() {
	const owner = Array.from(toasterOwners.entries()).at(-1);
	activeOwner.value = owner?.[0];
	getBrowserStore()?.setDefaultDuration(owner?.[1] ?? SONNER_DEFAULT_DURATION);
}

export const toast: SonnerToastApi = buildSonnerToastApi(storeFacade);

export interface UseToastReturn {
	toasts: ShallowRef<SonnerToast[]>;
	toast: SonnerToastApi;
	dismiss: (id?: string) => void;
	dismissAll: () => void;
}

export function useToast(): UseToastReturn {
	getBrowserStore();
	return {
		toasts,
		toast,
		dismiss: (id?: string) => toast.dismiss(id),
		dismissAll: () => toast.dismissAll(),
	};
}

function svgAttrs() {
	return {
		xmlns: 'http://www.w3.org/2000/svg',
		width: '16',
		height: '16',
		viewBox: '0 0 24 24',
		fill: 'none',
		stroke: 'currentColor',
		'stroke-width': '2',
		'stroke-linecap': 'round',
		'stroke-linejoin': 'round',
		'aria-hidden': 'true',
	};
}

function renderToastIcon(type: SonnerType) {
	switch (type) {
		case 'success':
			return h('svg', svgAttrs(), [h('circle', { cx: '12', cy: '12', r: '10' }), h('path', { d: 'm9 12 2 2 4-4' })]);
		case 'info':
			return h('svg', svgAttrs(), [h('circle', { cx: '12', cy: '12', r: '10' }), h('path', { d: 'M12 16v-4' }), h('path', { d: 'M12 8h.01' })]);
		case 'warning':
			return h('svg', svgAttrs(), [
				h('path', { d: 'm21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z' }),
				h('path', { d: 'M12 9v4' }),
				h('path', { d: 'M12 17h.01' }),
			]);
		case 'error':
			return h('svg', svgAttrs(), [h('path', { d: 'M13 2 3 14h9l-1 8 10-12h-9l1-8Z' })]);
		case 'loading':
			return h('svg', svgAttrs(), [h('path', { d: 'M21 12a9 9 0 1 1-6.219-8.56' })]);
		default:
			return null;
	}
}

function toastRole(type: SonnerType): 'alert' | 'status' {
	return type === 'error' || type === 'warning' ? 'alert' : 'status';
}

const closeIcon = h('svg', svgAttrs(), [h('path', { d: 'M18 6 6 18' }), h('path', { d: 'm6 6 12 12' })]);

export const Toaster = defineComponent({
	name: 'Toaster',
	inheritAttrs: false,
	props: {
		position: { type: String as PropType<SonnerPosition>, default: 'bottom-right' },
		duration: { type: Number, default: undefined },
		theme: { type: String as PropType<SonnerTheme>, default: undefined },
		richColors: { type: Boolean, default: false },
		closeButton: { type: Boolean, default: true },
	},
	setup(props, { attrs }) {
		const systemTheme = shallowRef<'light' | 'dark'>('light');
		const owner = Symbol('sonner-toaster-owner');
		let media: MediaQueryList | undefined;
		const updateSystemTheme = () => {
			systemTheme.value = media?.matches ? 'dark' : 'light';
		};

		watch(
			() => props.theme,
			(theme) => {
				media?.removeEventListener('change', updateSystemTheme);
				media = undefined;
				if (theme === 'system' && typeof window !== 'undefined') {
					media = window.matchMedia('(prefers-color-scheme: dark)');
					updateSystemTheme();
					media.addEventListener('change', updateSystemTheme);
				}
			},
			{ immediate: true },
		);

		onMounted(() => {
			getBrowserStore();
			toasterOwners.set(owner, props.duration);
			applyToasterPolicy();
		});

		onBeforeUnmount(() => {
			media?.removeEventListener('change', updateSystemTheme);
			toasterOwners.delete(owner);
			applyToasterPolicy();
		});

		watch(
			() => props.duration,
			(duration) => {
				if (!toasterOwners.has(owner)) return;
				toasterOwners.set(owner, duration);
				applyToasterPolicy();
			},
		);

		return () => {
			const resolvedTheme = resolveSonnerTheme(props.theme, systemTheme.value === 'dark');
			const userClass = attrs.class;
			const restAttrs = { ...attrs };
			delete restAttrs.class;
			const groups = new Map<string, SonnerToast[]>();
			for (const item of activeOwner.value === owner ? toasts.value : emptyToasts) {
				const key = item.position ?? props.position;
				const list = groups.get(key);
				if (list) {
					list.push(item);
				} else {
					groups.set(key, [item]);
				}
			}

			const containers: VNode[] = [];
			for (const [groupPosition, list] of groups) {
				const styleKeys = getSonnerPositionStyleKeys(groupPosition as SonnerPosition);
				const toastNodes = list.map((item) => {
					const children: VNode[] = [];
					const icon = renderToastIcon(item.type);
					if (icon) {
						children.push(h('div', { class: styles[sonnerStyleKeys.icon] }, [icon]));
					}
					children.push(
						h('div', { class: styles[sonnerStyleKeys.content] }, [
							item.title !== undefined ? h('div', { class: styles[sonnerStyleKeys.title] }, item.title) : null,
							item.description !== undefined ? h('div', { class: styles[sonnerStyleKeys.description] }, item.description) : null,
						]),
					);
					if (props.closeButton && item.dismissible !== false) {
						children.push(
							h(
								'button',
								{
									type: 'button',
									'aria-label': '关闭',
									class: styles[sonnerStyleKeys.close],
									onClick: () => toast.dismiss(item.id),
								},
								[closeIcon],
							),
						);
					}
					return h(
						'div',
						{
							key: item.id,
							role: toastRole(item.type),
							'aria-live': toastRole(item.type) === 'alert' ? 'assertive' : 'polite',
							'aria-atomic': 'true',
							'data-slot': 'toast',
							'data-type': item.type,
							'data-dismissing': item.dismissing ? 'true' : 'false',
							'data-rich-colors': item.richColors === undefined ? undefined : item.richColors ? 'true' : 'false',
							class: styles[sonnerStyleKeys.toast],
						},
						children,
					);
				});
				containers.push(
					h(
						'div',
						{
							...restAttrs,
							key: groupPosition,
							'data-slot': 'toaster',
							'data-theme': resolvedTheme,
							'data-rich-colors': props.richColors ? 'true' : undefined,
							class: [styles[styleKeys.base], styles[styleKeys.position], resolvedTheme, userClass],
						},
						toastNodes,
					),
				);
			}
			return containers;
		};
	},
});

export default Toaster;

@use '../../../styles/variables/colors' as *;

// Toaster 容器
.root {
	position: fixed;
	z-index: $z-modal;
	display: flex;
	flex-direction: column;
	gap: $spacing-2;
	width: max-content;
	max-width: calc(100vw - 2rem);
	pointer-events: none;

	&.positionTopLeft {
		top: $spacing-4;
		left: $spacing-4;
	}

	&.positionTopRight {
		top: $spacing-4;
		right: $spacing-4;
	}

	&.positionTopCenter {
		top: $spacing-4;
		left: 50%;
		transform: translateX(-50%);
	}

	&.positionBottomLeft {
		bottom: $spacing-4;
		left: $spacing-4;
	}

	&.positionBottomRight {
		right: $spacing-4;
		bottom: $spacing-4;
	}

	&.positionBottomCenter {
		bottom: $spacing-4;
		left: 50%;
		transform: translateX(-50%);
	}
}

// 单条提示
.toast {
	display: flex;
	align-items: center;
	gap: $spacing-3;
	min-width: 0;
	border: 1px solid var(--tile-toast-border, $border);
	border-radius: var(--tile-toast-radius, $radius);
	background-color: var(--tile-toast-background, $popover);
	color: $popover-foreground;
	padding: var(--tile-toast-padding, $spacing-3 $spacing-4);
	box-shadow: var(--tile-toast-shadow, $shadow-md);
	outline: var(--tile-toast-outline, none);
	pointer-events: auto;
	transition:
		opacity $transition-normal,
		transform $transition-normal;

	&[data-dismissing='true'] {
		opacity: 0;
		transform: translateY(0.5rem);
	}

	// Optional status surfaces and rings can style titles independently.
	// Unset tokens leave Tile's regular (non-rich) toast untouched.
	@each $type in success, info, warning, error {
		&[data-type='#{$type}'] {
			background-color: var(--tile-toast-#{$type}-background, var(--tile-toast-background, $popover));
			outline: var(--tile-toast-#{$type}-outline, var(--tile-toast-outline, none));

			.title {
				color: var(--tile-toast-#{$type}-title-color, inherit);
			}
		}
	}
}

// 图标
.icon {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	width: $spacing-5;
	height: $spacing-5;

	svg {
		width: $spacing-4;
		height: $spacing-4;
	}

	.toast[data-type='success'] & {
		color: var(--tile-toast-success-color, $success);
	}

	.toast[data-type='info'] & {
		color: var(--tile-toast-info-color, $info);
	}

	.toast[data-type='warning'] & {
		color: var(--tile-toast-warning-color, $warning);
	}

	.toast[data-type='error'] & {
		color: var(--tile-toast-error-color, $destructive);
	}
}

// 内容
.content {
	display: flex;
	min-width: 0;
	flex: 1;
	flex-direction: column;
}

// 标题
.title {
	font-size: var(--tile-toast-title-size, $text-sm);
	font-weight: $font-medium;
	line-height: var(--tile-toast-title-leading, $leading-tight);
}

// 描述
.description {
	margin-top: 0.125rem;
	font-size: var(--tile-toast-description-size, $text-sm);
	color: var(--tile-toast-description-color, $muted-foreground);
	line-height: var(--tile-toast-description-leading, $leading-normal);
}

// 富色模式：按类型着色整条提示
.root[data-rich-colors='true'] {
	.toast:not([data-rich-colors='false']) {
		border-color: transparent;

		&[data-type='success'] {
			background-color: var(--tile-toast-success-background, $success);
			color: var(--tile-toast-rich-color, $success-foreground);

			.icon {
				color: var(--tile-toast-success-color, $success-foreground);
			}
		}

		&[data-type='info'] {
			background-color: var(--tile-toast-info-background, $info);
			color: var(--tile-toast-rich-color, $info-foreground);

			.icon {
				color: var(--tile-toast-info-color, $info-foreground);
			}
		}

		&[data-type='warning'] {
			background-color: var(--tile-toast-warning-background, $warning);
			color: var(--tile-toast-rich-color, $warning-foreground);

			.icon {
				color: var(--tile-toast-warning-color, $warning-foreground);
			}
		}

		&[data-type='error'] {
			background-color: var(--tile-toast-error-background, $destructive);
			color: var(--tile-toast-rich-color, $destructive-foreground);

			.icon {
				color: var(--tile-toast-error-color, $destructive-foreground);
			}
		}
	}
}

.toast[data-rich-colors='true'] {
	border-color: transparent;

	&[data-type='success'] {
		background-color: var(--tile-toast-success-background, $success);
		color: var(--tile-toast-rich-color, $success-foreground);

		.icon {
			color: var(--tile-toast-success-color, $success-foreground);
		}
	}

	&[data-type='info'] {
		background-color: var(--tile-toast-info-background, $info);
		color: var(--tile-toast-rich-color, $info-foreground);

		.icon {
			color: var(--tile-toast-info-color, $info-foreground);
		}
	}

	&[data-type='warning'] {
		background-color: var(--tile-toast-warning-background, $warning);
		color: var(--tile-toast-rich-color, $warning-foreground);

		.icon {
			color: var(--tile-toast-warning-color, $warning-foreground);
		}
	}

	&[data-type='error'] {
		background-color: var(--tile-toast-error-background, $destructive);
		color: var(--tile-toast-rich-color, $destructive-foreground);

		.icon {
			color: var(--tile-toast-error-color, $destructive-foreground);
		}
	}
}

.root[data-rich-colors='true'] .toast:not([data-rich-colors='false']),
.toast[data-rich-colors='true'] {
	.description,
	.close,
	.close:hover {
		color: var(--tile-toast-rich-description-color, inherit);
	}
}

// 关闭按钮
.close {
	display: inline-flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	border: none;
	border-radius: var(--tile-toast-close-radius, $radius);
	background: transparent;
	color: $muted-foreground;
	cursor: pointer;
	padding: $spacing-1;
	transition:
		background-color $transition-fast,
		color $transition-fast;

	&:hover {
		background-color: var(--tile-toast-close-hover-background, $muted);
		color: $foreground;
	}

	svg {
		width: $spacing-4;
		height: $spacing-4;
	}
}

// 操作按钮容器
.actions {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	gap: $spacing-1;
}
